import {
  HalfKey,
  QuarterKey,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

export const MONTH_PERIOD_TYPES = [
  TimePeriodType.YTD,
  TimePeriodType.R3M,
  TimePeriodType.MTH,
] as const;

export type MonthPeriodType = (typeof MONTH_PERIOD_TYPES)[number];

export const QUARTERS = Object.values(QuarterKey) as QuarterKey[];
export const HALVES = Object.values(HalfKey) as HalfKey[];
